# f04 蒼穹の戦列 - 空だけのマップ。航空ユニットしか出せない。
# 眼下は全て海で、着陸できるのは自軍の飛行場だけ。
# **航空機は毎ターン燃料4を消費し、0で墜落する**（自軍の飛行場の上でのみ回復）。
# 戦闘機の燃料60＝15ターンぶん。前に出すぎると戦わずに落ちる。
# 前進基地の野戦飛行場は生産できないが補給できるので、ここが生命線になる。
# 拠点は誰も占領できない（占領は陸ユニットだけ）ので、決着は全滅のみ。180度回転対称。
[map]
name             = 蒼穹の戦列
width            = 46
height           = 30
turns            = 60
timeout_winner   = -1
funds0           = 4000
funds1           = 4000

